// 1. Get raw output from AI Agent Idea
const rawOutput = $json.output || "";

// 2. Clean up markdown code blocks if the AI wrapped the response in ```json ... ```
let cleanJson = rawOutput;
if (typeof rawOutput === 'string') {
  cleanJson = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
}

// 3. Parse JSON safely
let parsedData = {};
try {
  parsedData = typeof cleanJson === 'string' ? JSON.parse(cleanJson) : cleanJson;
} catch (e) {
  throw new Error("Failed to parse JSON from AI Agent output: " + e.message);
}

const ideas = parsedData.ideas || [];

if (!Array.isArray(ideas) || ideas.length === 0) {
  throw new Error("No ideas array found in AI output!");
}

// 4. Build Telegram Message Text
let messageText = "💡 *Select a Video Idea to Produce:*\n\n";
ideas.forEach(item => {
  messageText += `*${item.id}. ${item.title}*\n`;
  messageText += `• *Topic:* ${item.topic}\n`;
  messageText += `• *Hook:* ${item.hook}\n\n`;
});

// 5. Build Telegram Inline Keyboard Buttons
const inlineButtons = ideas.map(item => ([
  {
    text: `Select Idea #${item.id}`,
    callback_data: `select_idea_${item.id}`
  }
]));

// 6. Return structured output for the Telegram node
return {
  messageText,
  inlineButtons,
  ideas
};

// 1. Get raw output string from the AI Agent node
let rawOutput = $input.item.json.output || "";

// 2. Clean up markdown code blocks if present
rawOutput = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. Fix un-escaped line breaks and control characters inside the JSON string
rawOutput = rawOutput
  .replace(/[\r\n]+/g, '\\n')  // Escape raw line breaks inside string values
  .replace(/[\u0000-\u001F]+/g, ' '); // Strip non-printable control characters

let parsedData = {};

try {
  // 4. Parse string into a valid JSON object
  parsedData = JSON.parse(rawOutput);
} catch (error) {
  // Fallback regex extractor if JSON.parse still fails on malformed LLM outputs
  const titleMatch = rawOutput.match(/"title"\s*:\s*"([^"]*)"/);
  const slugMatch = rawOutput.match(/"slug"\s*:\s*"([^"]*)"/);
  const scriptMatch = rawOutput.match(/"script"\s*:\s*"([\s\S]*)"/);

  parsedData = {
    title: titleMatch ? titleMatch[1] : "",
    slug: slugMatch ? slugMatch[1] : "",
    script: scriptMatch ? scriptMatch[1].replace(/\\n/g, '\n') : rawOutput
  };
}

// 5. Extract script text and format breaks cleanly
const scriptText = (parsedData.script || "").replace(/\\n/g, '\n').trim();

// 6. Calculate stats
const words = scriptText.split(/\s+/).filter(w => w.length > 0);
const wordCount = words.length;

const WORDS_PER_MINUTE = 150;
const estimatedDurationMinutes = Math.round((wordCount / WORDS_PER_MINUTE) * 10) / 10;

// 7. Return cleanly structured item
return {
  title: parsedData.title || "",
  slug: parsedData.slug || "",
  script: scriptText,
  word_count: wordCount,
  estimated_duration_minutes: estimatedDurationMinutes
};

const words = $input.item.json.words || [];

if (words.length === 0) {
  return { formatted_transcript: "" };
}

// Helper function to format milliseconds to [M:SS] or [MM:SS]
function formatTime(ms) {
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `[${minutes}:${seconds.toString().padStart(2, '0')}]`;
}

let formattedLines = [];
let currentSentence = [];
let sentenceStartTime = words[0].start;

for (let i = 0; i < words.length; i++) {
  const wordObj = words[i];

  if (currentSentence.length === 0) {
    sentenceStartTime = wordObj.start;
  }

  currentSentence.push(wordObj.text);

  // Split on sentence-ending punctuation or pause detection
  const isPunctuationEnd = /[.!?]$/.test(wordObj.text);
  const isCommaPause = /,$/.test(wordObj.text) && currentSentence.length >= 6; // Also split long clauses if comma
  const isLastWord = (i === words.length - 1);

  if (isPunctuationEnd || isCommaPause || isLastWord) {
    const timeStampStr = formatTime(sentenceStartTime);
    const lineText = currentSentence.join(" ");

    formattedLines.push(`${timeStampStr} ${lineText}`);
    currentSentence = [];
  }
}

// Join all lines into a single clean formatted transcript text block
const fullFormattedTranscript = formattedLines.join("\n");

return {
  formatted_transcript: fullFormattedTranscript,
  lines: formattedLines
};

// 1. Get raw string output from Agent 3
let rawOutput = $input.item.json.output || "";

// 2. Remove markdown code blocks (```json ... ```)
rawOutput = rawOutput
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/g, '')
  .trim();

// 3. Fix un-escaped line breaks inside string literals
// First temporarily replace double escaped line breaks, then clean single unescaped newlines
let cleanedJSON = rawOutput
  .replace(/\\n/g, '__NEWLINE_PLACEHOLDER__')
  .replace(/[\r\n]+/g, ' ')
  .replace(/__NEWLINE_PLACEHOLDER__/g, '\\n');

let parsedData = {};

try {
  parsedData = JSON.parse(cleanedJSON);
} catch (error) {
  // Regex fallback: directly grab the JSON object structure {...}
  const match = cleanedJSON.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsedData = JSON.parse(match[0]);
    } catch (innerError) {
      throw new Error("Failed to parse cleaned JSON: " + innerError.message);
    }
  } else {
    throw new Error("Could not locate valid JSON structure in AI output.");
  }
}

// 4. Extract scenes array
const scenes = parsedData.scenes || [];

// 5. Output individual items for n8n to loop through each scene
return scenes.map((scene, index) => ({
  json: {
    scene_number: index + 1,
    timestamp: scene.timestamp || "",
    visual_description: scene.visual_description || "",
    image_prompt: scene.image_prompt || ""
  }
}));

// 1. Fetch loop items (your generated images)
const items = $('Loop Over Items').all();

// 2. Fetch original scene prompts / timestamps from Code in JavaScript3
const originalScenes = $('Code in JavaScript3').first().json.scenes || [];

// Helper to parse timestamp strings like "[0:07]" or "01:15" into pure seconds
function parseTimeToSeconds(val) {
  if (typeof val === 'number') return val;
  if (!val) return null;
  const match = String(val).match(/(\d+):(\d+)/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

// Track previous valid image URL to automatically fill in failed/empty generations
let lastValidImageUrl = "https://img.theapi.app/temp/092d7a69-2652-4b9f-ba51-5098aecf4c76.png"; 

// 3. Map over every loop item and align image + timing
const imageElements = items.map((item, index) => {
  const json = item.json || {};

  // Extract image URL safely across multiple possible keys
  let imageUrl = json.data?.output?.image_url || 
                 json.output?.image_url || 
                 json.image_url || 
                 json.data?.image_url || 
                 json.data?.output ||
                 json.output ||
                 "";

  // If imageUrl is valid, update fallback; if empty, reuse the last valid image
  if (typeof imageUrl === 'string' && imageUrl.startsWith('http')) {
    lastValidImageUrl = imageUrl;
  } else {
    imageUrl = lastValidImageUrl;
  }

  // Extract raw timestamp tag from original scenes array or item JSON
  const scene = originalScenes[index] || {};
  const rawTime = scene.timestamp || 
                  scene.input?.prompt?.match(/\[\d+:\d+\]/)?.[0] || 
                  json.data?.input?.prompt?.match(/\[\d+:\d+\]/)?.[0] || 
                  null;

  const parsedStart = parseTimeToSeconds(rawTime);
  // Spreads items across the full 314s duration if timestamps aren't parsed
  const startTime = parsedStart !== null ? parsedStart : Math.round((314 / items.length) * index);

  // Compute duration based on the start time of the subsequent scene
  let duration = null;
  if (index < items.length - 1) {
    const nextScene = originalScenes[index + 1] || {};
    const nextRawTime = nextScene.timestamp || 
                        nextScene.input?.prompt?.match(/\[\d+:\d+\]/)?.[0] || 
                        items[index + 1]?.json?.data?.input?.prompt?.match(/\[\d+:\d+\]/)?.[0] || 
                        null;

    const nextParsedStart = parseTimeToSeconds(nextRawTime);
    const nextStartTime = nextParsedStart !== null ? nextParsedStart : Math.round((314 / items.length) * (index + 1));
    duration = Math.max(1, nextStartTime - startTime);
  }

  return {
    type: "image",
    track: 1,
    time: startTime,
    duration: duration,
    source: imageUrl,
    fit: "cover"
  };
});

// 4. Fetch dynamic Cloudinary audio URL
const cloudinaryNode = $('HTTP Request8');
const audioUrl = cloudinaryNode.first().json.secure_url || cloudinaryNode.first().json.url;

// 5. Output clean RenderScript object for Creatomate
return {
  source: {
    output_format: "mp4",
    width: 1920,
    height: 1080,
    elements: [
      {
        type: "audio",
        track: 2,
        source: audioUrl
      },
      ...imageElements
    ]
  }
};

const source = $json.source;

const images = source.elements.filter(
  e => e.type === "image"
);

const audio = source.elements.find(
  e => e.type === "audio"
);

return {
  timeline: {
    tracks: [
      {
        clips: images.map(img => ({
          asset: {
            type: "image",
            src: img.source
          },
          start: img.time,
          length: img.duration || 15,
          fit: "cover" // Move fit to the clip level
        }))
      },
      {
        clips: [
          {
            asset: {
              type: "audio",
              src: audio ? audio.source : ""
            },
            start: 0,
            length: 314 // Required length for audio clip
          }
        ]
      }
    ]
  },
  output: {
    format: "mp4",
    resolution: "hd"
  }
};

